static int setup(const char* nm,const u8* d,int n){ int hid=0; memset(xhid_lay,0,sizeof xhid_lay); int k=hid_parse(d,n,xhid_lay[0],HIDLAY_MAX,&hid); xhid_nlay[0]=k; xhid_hasid[0]=hid; xhid_ccn[0]=0;
  int ms=-1; for(int q=0;q<k;q++) if(xhid_lay[0][q].kind==2)ms=q;
  char b[96]; snprintf(b,sizeof b,"%s: mouse layout with X and Y found",nm); chk(b,ms>=0&&xhid_lay[0][ms].x_off>=0&&xhid_lay[0][ms].y_off>=0); return ms; }
static void feed_x(int sl0,int ep,u8 cc,u32 res,u32 ptr){ (void)sl0; mouse_dx=mouse_dy=mouse_scroll=0; hid_xfer(3,ep,cc,res,ptr); }
static void feed(const u8* r,int n){ mouse_dx=mouse_dy=mouse_scroll=0; g_btn=0; hid_report_decode(0,r,n); }
static void put(u8* r,int bit,int sz,int v){ for(int i=0;i<sz;i++){ int p=bit+i; if((v>>i)&1)r[p>>3]|=(u8)(1<<(p&7)); else r[p>>3]&=(u8)~(1<<(p&7)); } }
static void motion(const char* nm,int idb,int xoff,int sz,int yoff,int len,int xv,int yv){ u8 r[64]; memset(r,0,sizeof r); int base=0; if(idb>=0){ r[0]=(u8)idb; base=8; }
  put(r,base+xoff,sz,xv); put(r,base+yoff,sz,yv); feed(r,len);
  char b[128]; snprintf(b,sizeof b,"%s: dx=%d dy=%d decoded (got %d,%d)",nm,xv,yv,mouse_dx,-mouse_dy); chk(b,mouse_dx==xv&&mouse_dy==-yv); }
